def money(value, currency):
	text = str(abs(int(round(value))))
	out = ""
	while len(text) > 3:
		out = "," + text[-3:] + out
		text = text[:-3]
	return currency + text + out

def noun(name, many):
	word = name
	if len(word) > 1 and word[1] == word[1].lower():
		word = word[0].lower() + word[1:]
	if not many:
		return word
	return word + "es" if word.endswith("s") else word + "s"

tiers = []
try:
	currency = str(props.get("currency") or "€")
	try:
		wanted = int(float(props.get("default_tier") or 2)) - 1
	except:
		wanted = 1
	try:
		most = max(1, int(float(props.get("max_quantity") or 10)))
	except:
		most = 10
	for raw in as_list(props.get("tiers")):
		parts = split_row(raw, 4)
		if not parts[0]:
			continue
		try:
			price = float(parts[1].replace(",", "").replace(currency, "").strip())
		except:
			price = 0
		status = parts[3]
		sold_out = status.lower().replace("-", " ") == "sold out"
		cap = most
		bits = status.lower().split(" ")
		if len(bits) == 2 and bits[1] == "left":
			try:
				cap = max(1, min(most, int(bits[0])))
			except:
				cap = most
		tiers.append({
			"slug": slugify(parts[0]),
			"name": parts[0],
			"price": str(int(round(price))),
			"price_label": money(price, currency),
			"includes": parts[2],
			"status": status,
			"has_status": len(status) > 0,
			"sold_out": "true" if sold_out else "false",
			"max": str(cap),
			"one": noun(parts[0], False),
			"many": noun(parts[0], True),
		})
	pick = wanted if 0 <= wanted < len(tiers) else 0
	if tiers and tiers[pick]["sold_out"] == "true":
		open_tiers = [i for i in range(len(tiers)) if tiers[i]["sold_out"] == "false"]
		pick = open_tiers[0] if open_tiers else 0
	marked = []
	for i in range(len(tiers)):
		row = tiers[i]
		row["checked"] = "true" if i == pick else "false"
		marked.append(row)
	tiers = marked
	if tiers:
		component.total = tiers[pick]["price_label"]
		component.buy = "Buy 1 " + tiers[pick]["one"]
	else:
		component.total = money(0, currency)
		component.buy = "Buy a pass"
	component.component_data = {"currency": currency}
except:
	tiers = []
	component.total = ""
	component.buy = "Buy a pass"
	component.component_data = {"currency": "€"}
component.tiers = tiers
